<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { NButton, NInput, NInputNumber, NSelect, NTag, NModal, NFormItem, NAlert, NTabs, NTab, NEmpty, useMessage, useDialog } from 'naive-ui';
import { kindLabels, kinds, type DocumentKind } from '@problemforge/contracts';
import { api, type Build } from '../api';
import SourceEditor from '../components/SourceEditor.vue';
import PdfPreview from '../components/PdfPreview.vue';
const templates = ref<any[]>([]); const version = ref<any>(); const templateId = ref(''); const fileName = ref('main.tex'); const files = ref<Record<string, string>>({}); const dirty = ref(false); const show = ref(false); const name = ref(''); const kind = ref<DocumentKind>('STATEMENT'); const busy = ref(false); const build = ref<Build>(); const panelTab = ref('preview'); const previewed = ref(false); const uploadInput = ref<HTMLInputElement>(); const message = useMessage(); const dialog = useDialog(); let timer: ReturnType<typeof setInterval>;
const styleConfig = ref({ marginMm: 24, cjkFont: 'Noto Serif CJK SC', palette: 'RED' }); const styleEdited = ref(false);
const loadError = ref(''); const loading = ref(false);
const imageFile = computed(() => /\.(png|jpe?g)$/.test(fileName.value));
const archivePreset = computed(() => !!files.value['preamble.tex']?.includes('fontset=overleaf'));
function changeStyle() { styleEdited.value = true; dirty.value = true; }
const editable = computed(() => version.value && ['DRAFT', 'VALIDATED'].includes(version.value.state));
const selectedTemplate = computed(() => templates.value.find(t => t.id === templateId.value));
async function load() { loading.value = true; loadError.value = ''; try { templates.value = await api('/admin/templates'); if (version.value) { const updated = templates.value.flatMap(t => t.versions).find(v => v.id === version.value.id); if (updated && !dirty.value) version.value = updated; } } catch (e) { loadError.value = (e as Error).message; } finally { loading.value = false; } }
function choose(t: any, v: any) { if (dirty.value && !window.confirm('放弃尚未保存的模板修改？')) return; templateId.value = t.id; version.value = v; files.value = { ...v.files }; styleConfig.value = v.styleConfig ?? { marginMm: t.kind === 'STATEMENT' ? 20 : 24, cjkFont: t.kind === 'EDITORIAL_BEAMER' ? 'Noto Sans CJK SC' : 'Noto Serif CJK SC', palette: 'RED' }; styleEdited.value = false; fileName.value = 'main.tex'; dirty.value = false; previewed.value = false; build.value = undefined; if (v.validationBuildId) inspect(v.validationBuildId); }
async function inspect(id: string) { build.value = await api(`/builds/${id}`); }
onMounted(async () => { await load(); const t = templates.value[0]; if (t?.versions[0]) choose(t, t.versions[0]); timer = setInterval(async () => { if (build.value && ['QUEUED', 'RUNNING'].includes(build.value.state)) { await inspect(build.value.id); if (build.value.state === 'SUCCEEDED') await load(); } }, 2000); }); onBeforeUnmount(() => clearInterval(timer));
onBeforeRouteLeave(() => !dirty.value || window.confirm('还有未保存的模板修改，确定离开吗？'));
async function create() { busy.value = true; try { const t = await api('/admin/templates', { method: 'POST', body: JSON.stringify({ name: name.value, kind: kind.value }) }); const starter = await api(`/admin/template-starters/${kind.value}`); const v = await api(`/admin/templates/${t.id}/versions`, { method: 'POST', body: JSON.stringify({ files: starter.files }) }); await load(); choose(t, v); show.value = false; } catch (e) { message.error((e as Error).message); } finally { busy.value = false; } }
async function save() { busy.value = true; try { const v = await api(`/admin/template-versions/${version.value.id}`, { method: 'PUT', body: JSON.stringify({ expectedVersion: version.value.editVersion, files: files.value, ...(styleEdited.value ? { styleConfig: styleConfig.value } : {}) }) }); version.value = v; files.value = { ...v.files }; dirty.value = false; styleEdited.value = false; previewed.value = false; build.value = undefined; await load(); message.success('模板草稿已保存，需重新验证'); return true; } catch (e) { message.error((e as Error).message); return false; } finally { busy.value = false; } }
async function newVersion() { try { const v = await api(`/admin/templates/${templateId.value}/versions`, { method: 'POST', body: JSON.stringify({ files: files.value }) }); await load(); choose(selectedTemplate.value, v); message.success('新草稿已创建，原版本保留'); } catch (e) { message.error((e as Error).message); } }
async function validate() { if (dirty.value && !await save()) return; try { const b = await api(`/admin/template-versions/${version.value.id}/validate`, { method: 'POST' }); build.value = { ...b, artifacts: [] }; previewed.value = false; panelTab.value = 'log'; } catch (e) { message.error((e as Error).message); } }
async function publish() { dialog.warning({ title: '发布管理员模板', content: '确认已检查此版本的真实 PDF 预览。发布后源码不可修改，已有题目绑定保持原版本。', positiveText: '发布此版本', negativeText: '返回', onPositiveClick: async () => { try { await api(`/admin/template-versions/${version.value.id}/publish`, { method: 'POST', body: JSON.stringify({ reviewedBuildId: build.value!.id }) }); await load(); message.success('模板已发布，可供新绑定选择'); } catch (e) { message.error((e as Error).message); } } }); }
async function archive() { await api(`/admin/template-versions/${version.value.id}/archive`, { method: 'POST' }); await load(); }
function revoke() { let reason = ''; dialog.warning({ title: '撤回模板版本', content: () => '撤回将阻止该版本的新构建。请输入原因：', positiveText: '撤回', negativeText: '返回', onPositiveClick: async () => { reason = window.prompt('撤回原因') ?? ''; if (!reason.trim()) return false; await api(`/admin/template-versions/${version.value.id}/revoke`, { method: 'POST', body: JSON.stringify({ reason }) }); await load(); } }); }
async function upload(event: Event) { try { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 10_000_000) throw new Error('模板包超过 10MB'); const parsed = JSON.parse(await file.text()); const imported = parsed.files ?? parsed; if (!editable.value) throw new Error('先创建可编辑草稿版本'); files.value = imported; dirty.value = true; message.info('模板包已载入编辑器，保存时由后端检查'); } catch (e) { message.error((e as Error).message); } }
</script>
<template><div class="page-heading"><div><h1>管理员模板中心</h1><p>题面、文档题解和 Beamer 模板独立版本化</p></div><NButton type="primary" @click="show = true">新建模板</NButton></div><NAlert v-if="loadError" type="error" class="spaced">模板列表加载失败：{{ loadError }} <NButton size="small" :loading="loading" @click="load">重试</NButton></NAlert><div class="template-layout"><aside class="panel template-list"><div v-for="t in templates" :key="t.id" class="template-group"><strong>{{ t.name }}</strong><small>{{ kindLabels[t.kind as DocumentKind] }}</small><button v-for="v in t.versions" :key="v.id" :class="['version-link', { selected: version?.id === v.id }]" @click="choose(t, v)"><span>v{{ v.number }}</span><NTag size="small" :type="v.state === 'PUBLISHED' ? 'success' : 'default'">{{ v.state }}</NTag></button></div><NEmpty v-if="!templates.length" description="创建第一套管理员模板" class="empty"/></aside><section class="panel template-editor" v-if="version"><div class="document-toolbar"><div><strong>{{ selectedTemplate?.name }} · v{{ version.number }}</strong><NTag size="small">{{ version.state }}</NTag></div><div><NButton size="small" @click="newVersion">复制为新版本</NButton><NButton v-if="editable" size="small" :loading="busy" @click="save">保存草稿</NButton><NButton v-if="editable" size="small" type="primary" @click="validate">验证样稿</NButton><NButton v-if="version.state === 'VALIDATED'" size="small" type="primary" :disabled="dirty || !build?.artifacts.length || !previewed" @click="publish">确认预览并发布</NButton><NButton v-if="version.state === 'PUBLISHED'" size="small" @click="archive">归档</NButton><NButton v-if="['PUBLISHED', 'ARCHIVED'].includes(version.state)" size="small" type="error" @click="revoke">撤回</NButton></div></div><NAlert v-if="!editable" :show-icon="false" type="info">发布版本不可原地修改。请复制为新草稿，既有绑定继续固定此版本。</NAlert><NAlert v-if="archivePreset" type="info" :show-icon="false">采用上传 main.tex 原版式：11pt、Overleaf 字体、双行页眉、原始页边距和 olymp 样例表格。下面的配置仅在管理员主动修改后覆盖原值。</NAlert><div class="admin-style-form"><label>中文字体<NSelect v-model:value="styleConfig.cjkFont" :disabled="!editable" :options="[{ label: 'Noto 宋体', value: 'Noto Serif CJK SC' }, { label: 'Noto 黑体', value: 'Noto Sans CJK SC' }]" @update:value="changeStyle" /></label><label v-if="selectedTemplate?.kind !== 'EDITORIAL_BEAMER'">页边距 (mm)<NInputNumber v-model:value="styleConfig.marginMm" :disabled="!editable" :min="15" :max="35" @update:value="changeStyle" /></label><label v-else>CWNU 配色<NSelect v-model:value="styleConfig.palette" :disabled="!editable" :options="[{ label: '参考红色', value: 'RED' }, { label: 'CWNU 蓝色', value: 'BLUE' }]" @update:value="changeStyle" /></label><span class="muted">管理员配置变化将重新生成 style.tex，并要求重新验证。</span></div><div class="template-tools"><NSelect v-model:value="fileName" :options="Object.keys(files).map(f => ({ label: f, value: f }))" style="width: 260px"/><span class="muted">{{ dirty ? '尚未保存' : `草稿编辑版本 ${version.editVersion}` }}</span><NButton v-if="editable" size="small" @click="uploadInput?.click()">上传模板包 JSON</NButton><input ref="uploadInput" type="file" accept="application/json,.json" hidden @change="upload"/></div><div class="editor-grid"><div v-if="imageFile" class="template-image"><img :src="`data:${fileName.endsWith('png') ? 'image/png' : 'image/jpeg'};base64,${files[fileName]}`" :alt="fileName"/><p>{{ fileName }} · 管理员模板资源</p></div><SourceEditor v-else v-model="files[fileName]" :key="version.id + fileName" :language="fileName.endsWith('.json') ? 'json' : fileName.endsWith('.yaml') ? 'yaml' : 'latex'" :readonly="!editable" @update:model-value="dirty = true"/><section class="result-pane"><NTabs v-model:value="panelTab" ><NTab name="preview">真实 PDF 预览</NTab><NTab name="log">验证日志</NTab></NTabs><NAlert v-if="build?.errorCode" type="error">{{ build.errorCode }}</NAlert><PdfPreview v-if="panelTab === 'preview'" :artifact-id="build?.artifacts[0]?.id" @loaded="previewed = true"/><pre v-else class="build-log">{{ build?.log || build?.state || '保存后提交代表性样稿验证' }}</pre></section></div></section></div><NModal v-model:show="show" preset="card" title="新建管理员模板" style="width: 480px"><NFormItem label="名称"><NInput v-model:value="name" placeholder="例如：简洁中文题面"/></NFormItem><NFormItem label="模板类型"><NSelect v-model:value="kind" :options="kinds.map(k => ({ label: kindLabels[k], value: k }))"/></NFormItem><p class="muted">会创建一份管理员可编辑的内置样式草稿，真实编译并确认后才能发布。</p><NButton type="primary" :loading="busy" :disabled="!name.trim()" @click="create">创建草稿</NButton></NModal></template>
